const std = @import("std");

pub fn main() !void {
    var arr = [_]i32{ 12, 45, 7, 23, 56, 18, 34, 9, 41 };
    const k: usize = 3;

    std.sort.block(i32, &arr, {}, struct {
        fn lessThan(_: void, a: i32, b: i32) bool { return a > b; }
    }.lessThan);

    std.debug.print("The {}rd largest is {}\n", .{k, arr[k - 1]});
}
